1	import { Agent, fetch as undiciFetch } from "undici";
2	
3	const insecureAgent = new Agent({ connect: { rejectUnauthorized: false } });
4	
5	const BASE = process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
6	const NODE = process.env.PROXMOX_NODE ?? "";
7	const TOKEN = `PVEAPIToken=${process.env.PROXMOX_TOKEN_ID}=${process.env.PROXMOX_TOKEN_SECRET}`;
8	
9	export class ProxmoxError extends Error {
10	  constructor(message: string, public status: number, public body?: string) {
11	    super(message);
12	  }
13	}
14	
15	async function pveRequestTo(
16	  base: string,
17	  token: string,
18	  method: "GET" | "POST" | "PUT" | "DELETE",
19	  path: string,
20	  params?: Record<string, string | number | undefined>
21	): Promise<any> {
22	  const url = new URL(`${base}/api2/json${path}`);
23	  let body: string | undefined;
24	  const headers: Record<string, string> = { Authorization: token };
25	
26	  const clean = Object.fromEntries(
27	    Object.entries(params ?? {}).filter(([, v]) => v !== undefined)
28	  ) as Record<string, string>;
29	
30	  if (method === "GET" || method === "DELETE") {
31	    for (const [k, v] of Object.entries(clean)) url.searchParams.set(k, String(v));
32	  } else {
33	    body = new URLSearchParams(clean as Record<string, string>).toString();
34	    headers["Content-Type"] = "application/x-www-form-urlencoded";
35	  }
36	
37	  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
38	  const text = await res.text();
39	  if (!res.ok) {
40	    throw new ProxmoxError(`PVE ${method} ${path} -> ${res.status}`, res.status, text);
41	  }
42	  try {
43	    return JSON.parse(text).data;
44	  } catch {
45	    return text;
46	  }
47	}
48	
49	function pveRequest(
50	  method: "GET" | "POST" | "PUT" | "DELETE",
51	  path: string,
52	  params?: Record<string, string | number | undefined>
53	) {
54	  return pveRequestTo(BASE, TOKEN, method, path, params);
55	}
56	
57	export const pve = {
58	  get: (path: string, params?: Record<string, any>) => pveRequest("GET", path, params),
59	  post: (path: string, params?: Record<string, any>) => pveRequest("POST", path, params),
60	  put: (path: string, params?: Record<string, any>) => pveRequest("PUT", path, params),
61	  del: (path: string, params?: Record<string, any>) => pveRequest("DELETE", path, params),
62	};
63	
64	export const node = NODE;
65	
66	/** Connection details for a specific Node row (see Prisma `Node`). */
67	export type NodeConn = {
68	  apiUrl: string;
69	  pveNode: string;
70	  tokenId: string;
71	  tokenSecret: string;
72	};
73	
74	export type PveClient = {
75	  get: (path: string, params?: Record<string, any>) => Promise<any>;
76	  post: (path: string, params?: Record<string, any>) => Promise<any>;
77	  put: (path: string, params?: Record<string, any>) => Promise<any>;
78	  del: (path: string, params?: Record<string, any>) => Promise<any>;
79	  node: string;
80	  waitForTask: (upid: string, timeoutMs?: number) => Promise<void>;
81	  nextVmid: () => Promise<number>;
82	  vmStatus: (vmid: number) => Promise<any>;
83	};
84	
85	/** Build a Proxmox client bound to a specific node. Use in the worker for multi-node. */
86	export function pveFor(conn: NodeConn): PveClient {
87	  const token = `PVEAPIToken=${conn.tokenId}=${conn.tokenSecret}`;
88	  const req = (m: "GET" | "POST" | "PUT" | "DELETE", path: string, params?: Record<string, any>) =>
89	    pveRequestTo(conn.apiUrl, token, m, path, params);
90	  const client: PveClient = {
91	    get: (p, params) => req("GET", p, params),
92	    post: (p, params) => req("POST", p, params),
93	    put: (p, params) => req("PUT", p, params),
94	    del: (p, params) => req("DELETE", p, params),
95	    node: conn.pveNode,
96	    async waitForTask(upid: string, timeoutMs = 300_000) {
97	      const start = Date.now();
98	      while (Date.now() - start < timeoutMs) {
99	        const status = await req("GET", `/nodes/${conn.pveNode}/tasks/${encodeURIComponent(upid)}/status`);
100	        if (status.status === "stopped") {
101	          if (status.exitstatus !== "OK") throw new Error(`Proxmox task failed: ${status.exitstatus}`);
102	          return;
103	        }
104	        await new Promise((r) => setTimeout(r, 2000));
105	      }
106	      throw new Error(`Proxmox task timed out: ${upid}`);
107	    },
108	    async nextVmid() {
109	      return Number(await req("GET", "/cluster/nextid"));
110	    },
111	    async vmStatus(vmid: number) {
112	      return req("GET", `/nodes/${conn.pveNode}/qemu/${vmid}/status/current`);
113	    },
114	  };
115	  return client;
116	}
117	
118	export async function waitForTask(upid: string, timeoutMs = 300_000): Promise<void> {
119	  const start = Date.now();
120	  while (Date.now() - start < timeoutMs) {
121	    const status = await pve.get(`/nodes/${NODE}/tasks/${encodeURIComponent(upid)}/status`);
122	    if (status.status === "stopped") {
123	      if (status.exitstatus !== "OK") {
124	        throw new Error(`Proxmox task failed: ${status.exitstatus}`);
125	      }
126	      return;
127	    }
128	    await new Promise((r) => setTimeout(r, 2000));
129	  }
130	  throw new Error(`Proxmox task timed out: ${upid}`);
131	}
132	
133	export async function nextVmid(): Promise<number> {
134	  const id = await pve.get("/cluster/nextid");
135	  return Number(id);
136	}
137	
138	export async function vmStatus(vmid: number): Promise<any> {
139	  return pve.get(`/nodes/${NODE}/qemu/${vmid}/status/current`);
140	}
141	
142	export async function nodeStatus(): Promise<any> {
143	  return pve.get(`/nodes/${NODE}/status`);
144	}
145	
146	export async function listVms(): Promise<any[]> {
147	  return pve.get(`/nodes/${NODE}/qemu`);
148	}
149	
150	/** Time-series metrics. timeframe: hour | day | week | month | year */
151	export async function vmRrd(vmid: number, timeframe = "hour"): Promise<any[]> {
152	  return pve.get(`/nodes/${NODE}/qemu/${vmid}/rrddata`, { timeframe, cf: "AVERAGE" });
153	}
154	
155	export async function nodeRrd(timeframe = "hour"): Promise<any[]> {
156	  return pve.get(`/nodes/${NODE}/rrddata`, { timeframe, cf: "AVERAGE" });
157	}
158	
159	export async function listSnapshots(vmid: number): Promise<any[]> {
160	  const snaps = await pve.get(`/nodes/${NODE}/qemu/${vmid}/snapshot`);
161	  return snaps.filter((s: any) => s.name !== "current");
162	}
163	
164	export async function listBackups(vmid?: number): Promise<any[]> {
165	  const content = await pve.get(`/nodes/${NODE}/storage/backup/content`, { content: "backup" });
166	  return vmid ? content.filter((b: any) => b.vmid === vmid) : content;
167	}
168	
169	export async function storageStatus(storage: string): Promise<any> {
170	  return pve.get(`/nodes/${NODE}/storage/${storage}/status`);
171	}
