21	function generatePassword(): string {
22	  // URL-safe, no ambiguous chars, 16 chars
23	  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
24	}
25	
26	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
27	  const server = await db.server.findUnique({
28	    where: { id: job.serverId! },
29	    include: { plan: true, osTemplate: true, node: true },
30	  });
31	  if (!server) throw new Error(`Server ${job.serverId} not found`);
32	  return server as any;
33	}
