35	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
36	async function nodeFor(server: any) {
37	  const n =
38	    server.node ??
39	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
40	    (await db.node.findFirst({ where: { enabled: true } }));
41	  if (!n) {
42	    // No Node rows yet — use the env-configured primary via the global client.
43	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
44	  }
45	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
46	}
