48	/** YAML-safe indent of a multi-line script under a `content: |` block. */
49	function indentBlock(text: string, spaces: number): string {
50	  const pad = " ".repeat(spaces);
51	  return text.split("\n").map((l) => pad + l).join("\n");
52	}
53	
54	/**
55	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
56	 * plus any control-panel/app install script and selected add-ons. Long installs
57	 * run in the background so the VM reports ready promptly.
58	 */
59	function buildCloudInit(server: any): string {
60	  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
61	  const setup: string[] = [];
62	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
63	  if (addons.malwareScanner)
64	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
65	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
66	
67	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
68	  return `#cloud-config
69	package_update: true
70	packages:
71	  - qemu-guest-agent
72	ssh_pwauth: true
73	disable_root: false
74	write_files:
75	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
76	    permissions: "0644"
77	    content: |
78	      PermitRootLogin yes
79	      PasswordAuthentication yes
80	  - path: /root/nxeon-setup.sh
81	    permissions: "0755"
82	    content: |
83	${indentBlock(script, 6)}
84	runcmd:
85	  - systemctl enable --now qemu-guest-agent
86	  - systemctl restart ssh || systemctl restart sshd
87	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
88	`;
89	}
90	
91	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
92	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
93	
94	async function provision(job: Job) {
95	  const server = await loadServer(job);
96	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
97	
98	  const { conn, row: nodeRow } = await nodeFor(server);
99	  const storage = server.plan.storageTier === "hdd"
100	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
101	    : nodeRow?.storageNvme ?? "vmdata";
102	
103	  const vmid = server.vmid ?? (await conn.nextVmid());
104	  const password = generatePassword();
105	
106	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
107	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
108	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
109	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
110	  const { getSettingBool: _settingBool } = await import("../lib/settings");
111	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
112	  if (wantDedicated && ovhConfigured()) {
113	    try {
114	      dedicated = await allocateDedicatedIp(server.id, vmid);
115	    } catch (e) {
116	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
117	    }
118	  }
119	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp()));
120	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort()));
121	
122	  await db.server.update({
123	    where: { id: server.id },
124	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
125	  });
126	
127	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
128	  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
129	    newid: vmid,
130	    name: server.hostname,
131	    full: 1,
132	    storage,
133	  });
134	  await conn.waitForTask(cloneUpid, 600_000);
135	
136	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
137	  const snippet = buildCloudInit(server);
138	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
139	    console.error("[worker] snippet write failed", e)
140	  );
141	
142	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
143	  const sshkeys = keys.length
144	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
145	    : undefined;
146	  const cfg: Record<string, any> = {
147	    cores: server.plan.cpuCores,
148	    memory: server.plan.ramMB,
149	    ciuser: "root",
150	    cipassword: password,
151	    sshkeys,
152	    nameserver: "1.1.1.1 8.8.8.8",
153	    onboot: 1,
154	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
155	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
156	  };
157	  if (dedicated) {
158	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
159	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
160	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
161	  } else {
162	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp()}`;
163	  }
164	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
165	
166	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
167	    disk: "scsi0",
168	    size: `${server.plan.diskGB}G`,
169	  });
170	
171	  if (!dedicated) await syncPortForwards();
172	
173	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
174	  await conn.waitForTask(startUpid);
175	
176	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
177	  const isImage = server.osTemplate.category !== "PLAIN_OS";
178	  const sshLine = dedicated
179	    ? `ssh root@${dedicated.address}`
180	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
181	  await notify(
182	    server.userId,
183	    `Server ${server.hostname} is ready`,
184	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
185	    `/dashboard/servers/${server.id}`
186	  );
187	}
