189	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
190	  const server = await loadServer(job);
191	  const { conn } = await nodeFor(server);
192	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
193	  await conn.waitForTask(upid);
194	  await db.server.update({
195	    where: { id: server.id },
196	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
197	  });
198	}
