200	async function destroyVm(conn: any, vmid: number) {
201	  // Stop first (ignore failure if already stopped), then destroy
202	  try {
203	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
204	    await conn.waitForTask(stopUpid);
205	  } catch {
206	    /* already stopped or does not exist */
207	  }
208	  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
209	    "destroy-unreferenced-disks": 1,
210	    purge: 1,
211	  });
212	  await conn.waitForTask(delUpid, 600_000);
213	}
214	
215	async function remove(job: Job) {
216	  const server = await loadServer(job);
217	  const { conn } = await nodeFor(server);
218	  if (server.vmid) {
219	    try {
220	      await destroyVm(conn, server.vmid);
221	    } catch (e: any) {
222	      // VM may never have been created; only swallow "does not exist"
223	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
224	    }
225	    // Best-effort: remove the per-server cloud-init snippet
226	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
227	  }
228	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC)
229	  await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
230	  await db.server.delete({ where: { id: server.id } });
231	  await syncPortForwards();
232	}
233	
234	async function reinstall(job: Job) {
235	  const server = await loadServer(job);
236	  const { conn } = await nodeFor(server);
237	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
238	  if (server.vmid) await destroyVm(conn, server.vmid);
239	  await provision(job);
240	}
241	
242	async function suspend(job: Job, unsuspend: boolean) {
243	  const server = await loadServer(job);
244	  const { conn } = await nodeFor(server);
245	  if (unsuspend) {
246	    // The dedicated IP was returned to the pool while suspended — re-allocate one
247	    // and reconfigure the public network before starting the VM back up.
248	    if (ovhConfigured() && server.vmid) {
249	      const { getSettingBool: _sb } = await import("../lib/settings");
250	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
251	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
252	      if (wantDedicated && !alreadyHas) {
253	        try {
254	          const d = await allocateDedicatedIp(server.id, server.vmid);
255	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
256	            net0: `virtio=${d.virtualMac},bridge=vmbr0`,
257	            ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
258	          });
259	          await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
260	        } catch (e) {
261	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; keeping current network", e);
262	        }
263	      }
264	    }
265	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
266	    await syncPortForwards();
267	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
268	    await conn.waitForTask(upid);
269	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
270	  } else {
271	    try {
272	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
273	      await conn.waitForTask(upid);
274	    } catch { /* may already be stopped */ }
275	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
276	    await syncPortForwards();
277	    // Return the dedicated IP to the pool while the server is suspended, so it
278	    // can be handed to a paying server. Re-allocated on unsuspend.
279	    if (ovhConfigured()) {
280	      try {
281	        await releaseDedicatedIp(server.id);
282	      } catch (e) {
283	        console.error("[worker] release dedicated IP on suspend failed", e);
284	      }
285	    }
286	  }
287	}
