297	async function resize(job: Job) {
298	  const server = await loadServer(job);
299	  const payload = (job.payload ?? {}) as { planId?: string };
300	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
301	  if (!newPlan) throw new Error("resize: target plan not found");
302	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
303	
304	  const { conn } = await nodeFor(server);
305	  const wasRunning = server.status === "RUNNING";
306	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
307	    cores: newPlan.cpuCores,
308	    memory: newPlan.ramMB,
309	  });
310	  if (newPlan.diskGB > server.plan.diskGB) {
311	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
312	      disk: "scsi0",
313	      size: `${newPlan.diskGB}G`,
314	    });
315	  }
316	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
317	  // CPU/RAM changes need a power cycle to apply
318	  if (wasRunning) {
319	    try {
320	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
321	      await conn.waitForTask(stopUpid, 120_000);
322	    } catch {
323	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
324	      await conn.waitForTask(stopUpid);
325	    }
326	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
327	    await conn.waitForTask(startUpid);
328	  }
329	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
330	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
