334	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
335	  const server = await loadServer(job);
336	  const payload = (job.payload ?? {}) as { name?: string };
337	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
338	  if (!name) throw new Error("snapshot: invalid name");
339	  const { conn } = await nodeFor(server);
340	  let upid: string;
341	  if (op === "create") {
342	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
343	  } else if (op === "delete") {
344	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
345	  } else {
346	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
347	  }
348	  await conn.waitForTask(upid, 600_000);
349	  if (op === "rollback") {
350	    // rollback leaves the VM stopped; bring it back if the server should be running
351	    const current = await db.server.findUnique({ where: { id: server.id } });
352	    if (current?.status === "RUNNING") {
353	      try {
354	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
355	        await conn.waitForTask(startUpid);
356	      } catch { /* may already be running */ }
357	    }
358	  }
359	}
