361	async function passwordReset(job: Job) {
362	  const server = await loadServer(job);
363	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
364	  const { conn } = await nodeFor(server);
365	  const password = generatePassword();
366	
367	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
368	  let applied = false;
369	  try {
370	    const upid = await conn.post(
371	      `/nodes/${conn.node}/qemu/${server.vmid}/agent/set-user-password`,
372	      { username: "root", password }
373	    );
374	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
375	    applied = true;
376	  } catch (e) {
377	    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
378	  }
379	
380	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
381	  if (!applied) {
382	    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
383	    if (server.status === "RUNNING") {
384	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
385	      await conn.waitForTask(upid);
386	    }
387	  }
388	
389	  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
390	  await notify(
391	    server.userId,
392	    `Root password reset for ${server.hostname}`,
393	    "Your new root password is available on the server's Overview tab.",
394	    `/dashboard/servers/${server.id}`
395	  );
396	}
