432	async function runJob(job: Job) {
433	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
434	  await db.job.update({
435	    where: { id: job.id },
436	    data: { status: "RUNNING", attempts: { increment: 1 } },
437	  });
438	  try {
439	    await handlers[job.type](job);
440	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
441	    console.log(`[worker] job ${job.id} DONE`);
442	  } catch (e: any) {
443	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
444	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
445	    const current = await db.job.findUnique({ where: { id: job.id } });
446	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
447	    await db.job.update({
448	      where: { id: job.id },
449	      data: { status: retriable ? "QUEUED" : "FAILED", error },
450	    });
451	    if (!retriable && job.serverId) {
452	      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
453	      if (stillExists) {
454	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
455	      }
456	    }
457	  }
458	}
