460	/**
461	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
462	 * killed worker leaves a job RUNNING forever, which permanently blocks the
463	 * server's "one in-flight job" guard and strands it in a transitional state.
464	 */
465	async function reapStuckJobs() {
466	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
467	  for (const job of stuck) {
468	    const retriable = job.attempts < MAX_ATTEMPTS;
469	    await db.job.update({
470	      where: { id: job.id },
471	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
472	    });
473	    if (!retriable && job.serverId) {
474	      const s = await db.server.findUnique({ where: { id: job.serverId } });
475	      if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
476	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
477	      }
478	    }
479	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
480	  }
481	}
