508	        await gameUpdateSweep();
509	      } catch (e) {
510	        console.error("[game-update] sweep error", e);
511	      }
512	    }
513	    // Geo-enrich recent visits (~90s) and run monitoring alerts (~10 min)
514	    if (Date.now() - lastGeoSweep > 90_000) {
