536	      }
537	    }
538	    // Pull newly-delivered OVH IPs into the pool every 5 min
539	    if (ovhConfigured() && Date.now() - lastIpSync > 5 * 60_000) {
540	      lastIpSync = Date.now();
541	      try {
542	        const r = await syncDedicatedIpPool();
543	        if (r.imported > 0) console.log(`[worker] dedicated IP pool: imported ${r.imported}, total ${r.total}`);
544	        // Low-pool alert, gated by the Settings toggle. (Auto-ordering IPs spends
545	        // real money via OVH and is intentionally left as a manual admin action.)
546	        const { getSettingBool, getSettingInt } = await import("../lib/settings");
547	        if (await getSettingBool("dedicated_ip_autoreplenish", false)) {
548	          const free = await db.dedicatedIp.count({ where: { status: "FREE" } });
549	          const threshold = await getSettingInt("dedicated_ip_replenish_threshold", 2);
550	          if (free < threshold) {
551	            const recent = await db.notification.findFirst({
552	              where: { title: { contains: "Dedicated IP pool low" }, createdAt: { gt: new Date(Date.now() - 6 * 3600_000) } },
553	            });
