21	    | "SNAPSHOT_CREATE"
22	    | "SNAPSHOT_DELETE"
23	    | "SNAPSHOT_ROLLBACK"
24	    | "BACKUP_CREATE"
25	    | "RESIZE"
26	    | "PASSWORD_RESET",
