5	/**
6	 * Self-service backup restore handler.
7	 *
8	 * Restores a selected vzdump archive back onto the server's existing VM via the
9	 * Proxmox API: stop -> restore (force overwrite) -> start. Ownership and archive
10	 * validation are enforced at enqueue time (`lib/actions-server-ops.ts`), so this
11	 * handler trusts the `volid` in the job payload.
12	 *
13	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire this in
14	 * there as `BACKUP_RESTORE: backupRestore`.
15	 */
16	
17	async function loadServer(serverId: string) {
18	  const server = await db.server.findUnique({
19	    where: { id: serverId },
20	    include: { node: true },
21	  });
22	  if (!server) throw new Error(`Server ${serverId} not found`);
23	  return server;
24	}
25	
26	/** Resolve a Proxmox client for the server's node (mirrors worker/index.ts). */
27	async function nodeFor(server: any) {
28	  const n =
29	    server.node ??
30	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
31	    (await db.node.findFirst({ where: { enabled: true } }));
32	  if (!n) {
33	    return {
34	      get: pve.get,
35	      post: pve.post,
36	      put: pve.put,
37	      del: pve.del,
38	      node: envNode,
39	      waitForTask,
40	      nextVmid,
41	      vmStatus: (v: number) => pve.get(`/nodes/${envNode}/qemu/${v}/status/current`),
42	    } as any;
43	  }
44	  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
45	}
46	
47	async function notify(userId: string, title: string, body?: string, href?: string) {
48	  try {
49	    await db.notification.create({ data: { userId, title, body, href } });
50	  } catch (e) {
51	    console.error("[restore] notify failed", e);
52	  }
53	}
