input.content:
"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { getSettingInt } from "./settings";
import { addMonths } from "./billing-terms";
import { debitWallet, InsufficientBalanceError } from "./wallet";

// Block storage volumes: add-on disks a customer can order, then attach to /
// detach from one of their running servers. A volume is billed per GB / month.
// The physical Proxmox disk only exists once a volume has been attached at least
// once; `Volume.diskName` tracks where that disk currently lives on the VM
// (`scsiN` while attached, `unusedN` while detached) and `Volume.serverId` the
// VM that physically holds it. See worker/volumes.ts for the Proxmox side.

const MIN_GB = 1;
const MAX_GB = 2000;

/** Price (in cents) for a volume of `sizeGB`, per-GB/month from Settings. */
export async function volumePriceCents(sizeGB: number): Promise<number> {
  const perGb = await getSettingInt("volume_price_cents_per_gb", 10);
  return Math.max(0, Math.round(sizeGB)) * perGb;
}

async function ownedVolume(volumeId: string) {
  const user = await requireUser();
  const volume = await db.volume.findUnique({ where: { id: volumeId } });
  if (!volume) throw new Error("Not found");
  if (volume.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, volume };
}

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Reject if the server already has a job queued or running (one in-flight per server). */
async function serverBusy(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

/**
 * Order a new block storage volume: debit the wallet up-front (one month) and
 * create the Volume row PENDING plus a VOLUME_CREATE job. The job flips it to
 * DETACHED (available to attach). No physical disk is created until attach.
 */
export async function orderVolume(
  name: string,
  sizeGB: number
): Promise<{ error?: string; id?: string }> {
  const user = await requireUser();

  const clean = (name ?? "")
    .replace(/[\x00-\x1f\x7f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (clean.length < 2 || clean.length > 40) {
    return { error: "Name must be 2–40 characters." };
  }
  const size = Math.round(Number(sizeGB));
  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
  }

  const priceCents = await volumePriceCents(size);

  let volumeId: string;
  try {
    volumeId = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, priceCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -priceCents,
          description: `Block storage volume: ${clean} (${size} GB)`,
        },
      });
      const v = await tx.volume.create({
        data: {
          userId: user.id,
          name: clean,
          sizeGB: size,
          priceCents,
          status: "PENDING",
          expiresAt: addMonths(new Date(), 1),
        },
      });
      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
      return v.id;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance — top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
  });
  revalidatePath("/dashboard/volumes");
  return { id: volumeId };
}

/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
export async function attachVolume(
  volumeId: string,
  serverId: string
): Promise<{ error?: string }> {
  const { user, volume } = await ownedVolume(volumeId);
  const { server } = await ownedServer(serverId);

  if (volume.status !== "DETACHED") {
    return { error: "Only an available (detached) volume can be attached." };
  }
  if (!server.vmid || server.status !== "RUNNING") {
    return { error: "Target server must be running." };
  }
  // A volume that already holds data physically lives on one server's VM; it can
  // only be re-attached there (cross-node disk migration is out of scope).
  if (volume.serverId && volume.serverId !== serverId) {
    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
  }
  if (await serverBusy(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.volume.update({ where: { id: volumeId }, data: { serverId } });
  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
  await db.auditLog.create({
    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
  });
  revalidatePath("/dashboard/volumes");
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

/** Detach an ATTACHED volume from its server (data is preserved as an unused disk). */
export async function detachVolume(volumeId: string): Promise<{ error?: string }> {
  const { user, volume } = await ownedVolume(volumeId);
  if (volume.status !== "ATTACHED" || !volume.serverId) {
    return { error: "Volume is not attached." };
  }
  if (await serverBusy(volume.serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }
  await db.job.create({
    data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId } },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "volume.detach", detail: `${volumeId}` },
  });
  revalidatePath("/dashboard/volumes");
  revalidatePath(`/dashboard/servers/${volume.serverId}`);
  return {};
}

/** Permanently delete a volume: detaches + destroys the disk, then removes the row. */
export async function deleteVolume(volumeId: string): Promise<{ error?: string }> {
  const { user, volume } = await ownedVolume(volumeId);
  if (volume.status === "DELETING") return { error: "Volume is already being deleted." };

  // If the disk physically lives on a server, route the delete through it and
  // honour the one-in-flight-job guard so we don't collide with another op.
  if (volume.serverId) {
    if (await serverBusy(volume.serverId)) {
      return { error: "Another operation is already in progress on this server." };
    }
  }
  await db.volume.update({ where: { id: volumeId }, data: { status: "DELETING" } });
  await db.job.create({
    data: {
      type: "VOLUME_DELETE",
      serverId: volume.serverId ?? undefined,
      payload: { volumeId },
    },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "volume.delete", detail: `${volumeId}` },
  });
  revalidatePath("/dashboard/volumes");
  if (volume.serverId) revalidatePath(`/dashboard/servers/${volume.serverId}`);
  return {};
}

"use client";

import { useMemo, useState, useTransition } from "react";
import { StatusDot, fmtMoney } from "@/components/ui/primitives";
import {
  orderVolume,
  attachVolume,
  detachVolume,
  deleteVolume,
} from "@/lib/actions-volumes";

export type VolumeRow = {
  id: string;
  name: string;
  sizeGB: number;
  priceCents: number;
  status: string;
  serverId: string | null;
  serverName: string | null;
};

export type ServerOption = { id: string; hostname: string };

/** Volume states in which no attach/detach/delete action should be offered. */
function isBusy(status: string): boolean {
  return status === "PENDING" || status === "DELETING";
}

function StatusLabel({ status }: { status: string }) {
  return <StatusDot status={status} />;
}

// ---------------------------------------------------------------------------
// Create form
// ---------------------------------------------------------------------------

function CreateVolume({ perGbCents }: { perGbCents: number }) {
  const [name, setName] = useState("");
  const [size, setSize] = useState(10);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const monthly = Math.max(0, Math.round(size)) * perGbCents;

  return (
    <div className="card p-5">
      <h3 className="text-base font-semibold">New volume</h3>
      <p className="mt-1 text-sm text-slate-400">
        Order an add-on disk, then attach it to any of your running servers.
      </p>
      <div className="mt-4 flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Name</label>
          <input
            className="input w-56"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="data-disk"
            maxLength={40}
            disabled={pending}
          />
        </div>
        <div>
          <label className="label">Size (GB)</label>
          <input
            className="input w-32"
            type="number"
            min={1}
            max={2000}
            value={size}
            onChange={(e) => setSize(Number(e.target.value))}
            disabled={pending}
          />
        </div>
        <div className="pb-1 text-sm text-slate-400">
          <span className="font-semibold text-slate-100">{fmtMoney(monthly)}</span> / month
        </div>
        <button
          className="btn-primary"
          disabled={pending || name.trim().length < 2 || size < 1}
          onClick={() =>
            start(async () => {
              setError(null);
              const res = await orderVolume(name.trim(), size);
              if (res?.error) setError(res.error);
              else {
                setName("");
                setSize(10);
              }
            })
          }
        >
          {pending ? "Ordering…" : "Order volume"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <p className="mt-2 text-xs text-slate-500">
        Billed monthly at {fmtMoney(perGbCents)} per GB. Charged now from your wallet.
      </p>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Row actions (attach / detach / delete)
// ---------------------------------------------------------------------------

function VolumeActions({
  volume,
  servers,
}: {
  volume: VolumeRow;
  servers: ServerOption[];
}) {
  const [target, setTarget] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      const res = await fn();
      if (res?.error) setError(res.error);
    });
  };

  const busy = isBusy(volume.status);
  // A volume that already holds data is pinned to its server; only offer that one.
  const options = volume.serverId
    ? servers.filter((s) => s.id === volume.serverId)
    : servers;

  return (
    <div className="flex flex-col items-end gap-2">
      <div className="flex items-center gap-2">
        {error && <span className="text-xs text-red-400">{error}</span>}

        {volume.status === "DETACHED" && (
          <>
            <select
              className="input w-44 py-1.5 text-xs"
              value={target}
              onChange={(e) => setTarget(e.target.value)}
              disabled={pending || options.length === 0}
            >
              <option value="">
                {options.length === 0 ? "No running servers" : "Attach to…"}
              </option>
              {options.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.hostname}
                </option>
              ))}
            </select>
            <button
              className="btn-secondary px-3 py-1 text-xs"
              disabled={pending || !target}
              onClick={() => run(() => attachVolume(volume.id, target))}
            >
              Attach
            </button>
          </>
        )}

        {volume.status === "ATTACHED" && (
          <button
            className="btn-secondary px-3 py-1 text-xs"
            disabled={pending}
            onClick={() =>
              run(
                () => detachVolume(volume.id),
                `Detach "${volume.name}" from ${volume.serverName ?? "its server"}? Data is preserved.`
              )
            }
          >
            Detach
          </button>
        )}

        <button
          className="btn-danger px-3 py-1 text-xs"
          disabled={pending || busy}
          onClick={() =>
            run(
              () => deleteVolume(volume.id),
              `Delete volume "${volume.name}" (${volume.sizeGB} GB)? This permanently destroys its data and cannot be undone.`
            )
          }
        >
          Delete
        </button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Full manager (dashboard page)
// ---------------------------------------------------------------------------

export function Volumes({
  volumes,
  servers,
  perGbCents,
}: {
  volumes: VolumeRow[];
  servers: ServerOption[];
  perGbCents: number;
}) {
  return (
    <div className="space-y-6">
      <CreateVolume perGbCents={perGbCents} />

      {volumes.length === 0 ? (
        <div className="card p-8 text-center text-sm text-slate-400">
          No volumes yet. Order one above to add extra disk space to a server.
        </div>
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Name</th>
                <th>Size</th>
                <th>Price / mo</th>
                <th>Status</th>
                <th>Attached to</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {volumes.map((v) => (
                <tr key={v.id}>
                  <td className="font-medium text-slate-100">{v.name}</td>
                  <td>{v.sizeGB} GB</td>
                  <td>{fmtMoney(v.priceCents)}</td>
                  <td>
                    <StatusLabel status={v.status} />
                  </td>
                  <td className="text-slate-400">{v.serverName ?? "—"}</td>
                  <td>
                    <VolumeActions volume={v} servers={servers} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Compact panel for a single server page
// ---------------------------------------------------------------------------

export function ServerVolumesPanel({
  serverId,
  serverHostname,
  serverRunning,
  attached,
  available,
}: {
  serverId: string;
  serverHostname: string;
  serverRunning: boolean;
  /** Volumes currently attached to this server. */
  attached: VolumeRow[];
  /** Caller's DETACHED volumes that can be attached here (already ownership-filtered). */
  available: VolumeRow[];
}) {
  const [target, setTarget] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const attachable = useMemo(
    () => available.filter((v) => !v.serverId || v.serverId === serverId),
    [available, serverId]
  );

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      const res = await fn();
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="card p-5">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-base font-semibold">Block storage</h3>
          <p className="mt-1 text-sm text-slate-400">Add-on disks attached to this server.</p>
        </div>
      </div>

      {attached.length > 0 && (
        <div className="mt-4 space-y-2">
          {attached.map((v) => (
            <div
              key={v.id}
              className="flex items-center justify-between rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2"
            >
              <div className="text-sm">
                <span className="font-medium text-slate-100">{v.name}</span>{" "}
                <span className="text-slate-400">· {v.sizeGB} GB</span>
              </div>
              <div className="flex items-center gap-2">
                <StatusLabel status={v.status} />
                <button
                  className="btn-secondary px-3 py-1 text-xs"
                  disabled={pending || isBusy(v.status)}
                  onClick={() =>
                    run(
                      () => detachVolume(v.id),
                      `Detach "${v.name}" from ${serverHostname}? Data is preserved.`
                    )
                  }
                >
                  Detach
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="mt-4 flex flex-wrap items-center gap-2">
        <select
          className="input w-52 py-1.5 text-xs"
          value={target}
          onChange={(e) => setTarget(e.target.value)}
          disabled={pending || !serverRunning || attachable.length === 0}
        >
          <option value="">
            {attachable.length === 0 ? "No available volumes" : "Attach a volume…"}
          </option>
          {attachable.map((v) => (
            <option key={v.id} value={v.id}>
              {v.name} ({v.sizeGB} GB)
            </option>
          ))}
        </select>
        <button
          className="btn-secondary px-3 py-1 text-xs"
          disabled={pending || !target || !serverRunning}
          onClick={() => run(() => attachVolume(target, serverId))}
        >
          Attach
        </button>
        {!serverRunning && (
          <span className="text-xs text-slate-500">Server must be running to attach.</span>
        )}
      </div>

      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      {attached.length === 0 && (
        <p className="mt-3 text-xs text-slate-500">No volumes attached yet.</p>
      )}
    </div>
  );
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { getSettingInt } from "@/lib/settings";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageHeader } from "@/components/ui/primitives";
import { Volumes, type VolumeRow, type ServerOption } from "@/components/customer/Volumes";

export const dynamic = "force-dynamic";

export default async function VolumesPage() {
  const user = await requireUser();

  const [volumes, servers, perGbCents] = await Promise.all([
    db.volume.findMany({
      where: { userId: user.id },
      include: { server: true },
      orderBy: { createdAt: "desc" },
    }),
    db.server.findMany({
      where: { userId: user.id, status: "RUNNING" },
      orderBy: { createdAt: "desc" },
    }),
    getSettingInt("volume_price_cents_per_gb", 10),
  ]);

  const rows: VolumeRow[] = volumes.map((v) => ({
    id: v.id,
    name: v.name,
    sizeGB: v.sizeGB,
    priceCents: v.priceCents,
    status: v.status,
    serverId: v.serverId,
    serverName: v.server ? v.server.hostname : null,
  }));

  const serverOptions: ServerOption[] = servers.map((s) => ({
    id: s.id,
    hostname: s.hostname,
  }));

  const transitional = volumes.some((v) => ["PENDING", "DELETING"].includes(v.status));

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PageHeader
        title="Block Storage"
        sub="Add-on volumes you can attach to any of your running servers."
      />
      <Volumes volumes={rows} servers={serverOptions} perGbCents={perGbCents} />
    </div>
  );
}

import { db } from "../lib/db";
import { pve, node as envNode, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
import type { Job } from "@prisma/client";

/**
 * Block storage volume handlers (add-on disks attached to a VPS).
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire these in there:
 *   VOLUME_CREATE: volumeCreate,
 *   VOLUME_ATTACH: volumeAttach,
 *   VOLUME_DETACH: volumeDetach,
 *   VOLUME_DELETE: volumeDelete,
 *
 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
 * so these handlers trust `payload.volumeId`.
 *
 * A volume's underlying Proxmox disk only exists once it has been attached at
 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
 * changes across detach/re-attach; we always re-scan the VM config to find the
 * disk's current key (scsiN while attached, unusedN while detached).
 */

type Vol = Awaited<ReturnType<typeof loadVolume>>;

async function loadVolume(job: Job) {
  const payload = (job.payload ?? {}) as { volumeId?: string };
  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
  const volume = await db.volume.findUnique({
    where: { id: payload.volumeId },
    include: { server: { include: { node: true } } },
  });
  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
  return volume;
}

/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
async function nodeFor(server: any) {
  const n =
    server?.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    return {
      conn: {
        get: pve.get,
        post: pve.post,
        put: pve.put,
        del: pve.del,
        node: envNode,
        waitForTask,
        nextVmid,
        vmStatus,
      } as any,
      row: null,
    };
  }
  return {
    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
    row: n,
  };
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[volumes] notify failed", e);
  }
}

/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
function volidOf(configValue: unknown): string {
  return String(configValue ?? "").split(",")[0].trim();
}

/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
function freeScsiSlot(config: Record<string, any>): string {
  for (let i = 1; i <= 30; i++) {
    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
  }
  throw new Error("no free scsi slot available on this VM");
}

/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
function keyForVolid(config: Record<string, any>, volid: string): string | null {
  for (const [k, v] of Object.entries(config)) {
    if (typeof v === "string" && volidOf(v) === volid) return k;
  }
  return null;
}

/**
 * VOLUME_CREATE — logical registration only. No physical disk is created until
 * the volume is first attached (a Proxmox disk must live on a VM). Flip the row
 * from PENDING to DETACHED so the customer can attach it.
 */
export async function volumeCreate(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  if (volume.status === "PENDING") {
    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
  }
  await notify(
    volume.userId,
    `Volume "${volume.name}" is ready`,
    `${volume.sizeGB} GB block storage is available to attach to a server.`,
    "/dashboard/volumes"
  );
}

/**
 * VOLUME_ATTACH — attach the disk to the target server's VM at a free scsi slot.
 * Creates the underlying disk on first attach ("<storage>:<sizeGB>"); on a
 * re-attach it re-uses the existing volume id so data is preserved.
 */
export async function volumeAttach(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;
  if (!server || !server.vmid) throw new Error("volume attach: server has no VM");

  const { conn, row } = await nodeFor(server);
  const storage = row?.storageNvme ?? "vmdata";

  const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
  const slot = freeScsiSlot(config);

  // Re-use the existing disk (by volid) if this volume was attached before;
  // otherwise let Proxmox create a fresh <storage>:<sizeGB> disk.
  const source = volume.diskName ? volume.diskName : `${storage}:${volume.sizeGB}`;
  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { [slot]: source });

  // Read back the real volume id Proxmox assigned/kept at the slot.
  const after = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
  const volid = volidOf(after[slot]) || volume.diskName || null;

  await db.volume.update({
    where: { id: volume.id },
    data: { status: "ATTACHED", serverId: server.id, diskName: volid },
  });
  await notify(
    volume.userId,
    `Volume "${volume.name}" attached to ${server.hostname}`,
    `${volume.sizeGB} GB is now available as ${slot}. Format and mount it inside the server to use it.`,
    `/dashboard/servers/${server.id}`
  );
}

/**
 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
 * entry, preserving the data). The volume stays pinned to this server so it can
 * be re-attached here later.
 */
export async function volumeDetach(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;

  if (server?.vmid && volume.diskName) {
    const { conn } = await nodeFor(server);
    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
    const key = keyForVolid(config, volume.diskName);
    if (key && key.startsWith("scsi")) {
      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
    }
  }

  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
  if (server) {
    await notify(
      volume.userId,
      `Volume "${volume.name}" detached from ${server.hostname}`,
      "The volume and its data are preserved and can be re-attached to the same server.",
      "/dashboard/volumes"
    );
  }
}

/**
 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
 * disk, and remove the Volume row.
 */
export async function volumeDelete(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;

  if (server?.vmid && volume.diskName) {
    const { conn } = await nodeFor(server);
    try {
      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
      let key = keyForVolid(config, volume.diskName);

      // If still mounted, detach to an "unused" entry first.
      if (key && key.startsWith("scsi")) {
        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
        config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
        key = keyForVolid(config, volume.diskName);
      }
      // Deleting an "unused" entry destroys the underlying disk.
      if (key) {
        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
      }
    } catch (e: any) {
      const msg = String(e?.body ?? e?.message ?? e);
      if (!msg.includes("does not exist")) throw e;
    }
  }

  await db.volume.delete({ where: { id: volume.id } });
  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
}

